examples.code:
job "web" {
  group "app" {
    count = 3   # desired replica count

    task "server" {
      driver = "docker"
      config {
        image = "myorg/web:1.4.0"
      }
    }
  }
}

job "web-app" {
  datacenters = ["dc1"]

  group "web" {
    count = 3

    update {
      max_parallel = 1
      canary       = 1
    }

    task "server" {
      driver = "docker"
      config {
        image = "myorg/web-app:2.3.0"
        ports = ["http"]
      }
      resources {
        cpu    = 500
        memory = 256
      }
    }

    network {
      port "http" { to = 8080 }
    }
  }
}

job "train-llm" {
  type        = "batch"
  datacenters = ["dc1", "dc2"]

  constraint {
    attribute = "${node.class}"
    value     = "gpu-rack-a"
  }

  group "trainer" {
    count = 1

    task "train" {
      driver = "docker"
      config {
        image = "myorg/trainer:2.1.0"
      }
      resources {
        cpu    = 4000
        memory = 16384
        device "nvidia/gpu" {
          count = 4
        }
      }
    }
  }
}

job "gpu-metrics-agent" {
  type        = "system"   # one instance per eligible node
  datacenters = ["dc1", "dc2"]

  group "agent" {
    task "exporter" {
      driver = "docker"
      config {
        image = "myorg/gpu-metrics-exporter:1.0.0"
      }
    }
  }
}
